import { Component, ComponentInterface, h, Host, Listen } from '@stencil/core';
import { DrillDownChangeEvent } from '../../../../../types';

@Component({
  tag: 'groupui-local-side-navigation-items',
  styleUrl: 'local-side-navigation-items.scss',
  shadow: true,
})
export class LocalSideNavigationItems implements ComponentInterface {
  @Listen('groupuiDrilldownChange')
  handleDrilldownChange(event: CustomEvent<DrillDownChangeEvent>): void {
    event.stopImmediatePropagation();
    const { open, element } = event.detail;

    if (open) {
      this.inertSiblingsAndButton(element);
    } else {
      this.uninertSiblingsAndButton(element);
    }
  }

  /**
   * Makes sibling navigation items and the drilldown's own button inert to prevent keyboard navigation.
   * This ensures only the drilldown content remains accessible when the drilldown is open.
   *
   * @param drilldownElement - The drilldown item element that was opened
   */
  private inertSiblingsAndButton(drilldownElement: HTMLElement): void {
    const parent = drilldownElement.parentElement;
    if (!parent) return;
    const drillDownSiblings = Array.from(parent.children).filter((child) => child !== drilldownElement);

    drillDownSiblings.forEach((sibling) => {
      sibling.setAttribute('inert', '');
    });
    drilldownElement.shadowRoot?.querySelector('button')?.setAttribute('inert', '');
  }

  /**
   * Removes inert attributes from sibling navigation items and the drilldown's own button.
   * This restores normal keyboard navigation when the drilldown is closed.
   *
   * @param drilldownElement - The drilldown item element that was closed
   */
  private uninertSiblingsAndButton(drilldownElement: HTMLElement): void {
    const parent = drilldownElement.parentElement;
    if (!parent) return;

    Array.from(parent.children).forEach((sibling) => {
      sibling.removeAttribute('inert');
    });
    const shadowRoot = drilldownElement.shadowRoot;
    if (shadowRoot) {
      const button = shadowRoot.querySelector('button');
      if (button) {
        button.removeAttribute('inert');
      }
    }
  }

  render() {
    return (
      <Host slot="nav-items">
        <div>
          <slot></slot>
        </div>
      </Host>
    );
  }
}
